css:
.gc { width: 85.6mm; min-height: 54mm; border: 1px solid #14213D; border-radius: 3mm; padding: 3mm 3.5mm; font-size: 10px; box-sizing: border-box; }
.gc .top { display: flex; justify-content: space-between; align-items: center; border-bottom: 1.5px solid #14213D; padding-bottom: 1.5mm; margin-bottom: 1.5mm; }
.gc .top b { font-size: 12px; color: #14213D; }
.gc .ar { direction: rtl; font-family: 'Tahoma', 'Arial', sans-serif; }
.gc .body { display: flex; gap: 2.5mm; align-items: flex-start; }
.gc table { flex: 1; border-collapse: collapse; }
.gc td { padding: 0.7mm 0; vertical-align: top; }
.gc td.l { color: #555; font-size: 8.5px; width: 13mm; white-space: nowrap; padding-top: 1mm; }
.gc td.r { color: #555; font-size: 8.5px; width: 14mm; white-space: nowrap; text-align: right; padding-top: 1mm; }
.gc td.v { font-weight: bold; padding: 0.7mm 1.5mm; word-break: break-word; }
.gc .gun { font-size: 13px; letter-spacing: 0.03em; }
.gc .qr img { width: 17mm; height: 17mm; display: block; }

html:
{%- set c = frappe.db.get_value("Customer", doc.customer, ["customer_name", "mobile_no", "armak_civil_id"], as_dict=True) -%}
{%- macro row(en, ar, value, cls="") -%}
<tr><td class="l">{{ en }}</td><td class="v {{ cls }}">{{ value or "" }}</td><td class="r ar">{{ ar }}</td></tr>
{%- endmacro -%}
<div class="gc">
  <div class="top">
    <b>GUN CARD</b>
    <span class="ar"><b>بطاقة السلاح</b></span>
  </div>
  <div class="body">
    <table>
      {{ row("Name", "الاسم", c.customer_name) }}
      {{ row("Phone", "الهاتف", c.mobile_no) }}
      {{ row("ID", "الرقم المدني", c.armak_civil_id) }}
      {{ row("Gun No", "رقم السلاح", doc.gun_number, "gun") }}
      {%- if doc.gun_type or doc.make %}{{ row("Type", "النوع", [doc.gun_type, doc.make] | select | join(" · ")) }}{% endif %}
      {%- if doc.licence_no %}{{ row("Licence", "الترخيص", doc.licence_no) }}{% endif %}
    </table>
    <div class="qr"><img src="{{ qr_data_uri(doc.gun_number) }}"></div>
  </div>
</div>
